using System;using System.Collections.Generic;using UnityEngine;using UnityEngine.Rendering;using UnityEditor;
public static partial class AtelierBuild {
 static void RefineDetails(){var supply=Part("M05-S");var group=Group("External flanged steam piping",supply.transform,-supply.home);var copper=Mat("Annealed copper",C("9E512C"),.76f,.50f);
  for(int sign=-1;sign<=1;sign+=2){var controls=new[]{V(.35f,3.00f,sign*.26f),V(1.95f,3.00f,sign*.27f),V(2.30f,2.96f,sign*.43f),V(2.43f,2.71f,sign*.70f),V(2.44f,1.75f,sign*.88f),V(2.65f,1.36f,sign*1.0f),V(3.05f,1.18f,sign*1.085f)};var points=new List<Vector3>();for(int i=0;i<controls.Length-1;i++){var p0=controls[Mathf.Max(0,i-1)];var p1=controls[i];var p2=controls[i+1];var p3=controls[Mathf.Min(controls.Length-1,i+2)];for(int j=0;j<9;j++){float t=j/9f;points.Add(.5f*((2*p1)+(-p0+p2)*t+(2*p0-5*p1+4*p2-p3)*t*t+(-p0+3*p1-3*p2+p3)*t*t*t));}}points.Add(controls[controls.Length-1]);Tube("Continuous copper steam riser",group,points.ToArray(),.027f,copper,16);foreach(int index in new[]{1,3,5}){Vector3 p=controls[index],d=(controls[index+1]-controls[index-1]).normalized;Cylinder("Pipe union",group,p-d*.035f,p+d*.035f,.045f,brass,12);}Cylinder("Steam valve spindle",group,V(2.04f,3.00f,sign*.27f),V(2.04f,3.24f,sign*.27f),.026f,brass);Lathe("Steam stop valve bonnet",group,V(2.04f,3.13f,sign*.27f),new[]{new Vector2(0,0),new Vector2(.06f,0),new Vector2(.06f,.10f),new Vector2(.04f,.12f),new Vector2(0,.12f)},brass,24);}
  MergeStatic(group);
  var cab=Part("P04");var windows=Group("Round front cab portholes",cab.transform,-cab.home);for(int sign=-1;sign<=1;sign+=2){Vector3 centre=V(-.803f,2.685f,sign*.985f);var vs=new List<Vector3>();var tris=new List<int>();for(int i=0;i<=48;i++){float a=i*2*Mathf.PI/48;float yy=Mathf.Cos(a),zz=Mathf.Sin(a),extent=Mathf.Min(.307f/Mathf.Max(.0001f,Mathf.Abs(yy)),.164f/Mathf.Max(.0001f,Mathf.Abs(zz)));vs.Add(centre+V(0,yy*.132f,zz*.132f));vs.Add(centre+V(0,yy*extent,zz*extent));if(i>0){int k=i*2;tris.AddRange(new[]{k-2,k-1,k+1,k-2,k+1,k});}}var mesh=new Mesh();mesh.SetVertices(vs);mesh.SetTriangles(tris,0);mesh.RecalculateNormals();MeshObject("Porthole infill plate",windows,SaveMesh(mesh,"Porthole_"+sign),navy);var ring=new List<Vector3>();for(int i=0;i<=48;i++){float a=i*2*Mathf.PI/48;ring.Add(centre+V(.012f,Mathf.Cos(a)*.137f,Mathf.Sin(a)*.137f));}Tube("Brass porthole rim",windows,ring.ToArray(),.012f,brass,12);}MergeStatic(windows);
 }
 static void AddReflections(Transform stage){foreach(Transform child in stage)if(child.name=="Daylit atelier"||child.name=="Solid oak teaching workbench")foreach(var t in child.GetComponentsInChildren<Transform>(true))t.gameObject.layer=28;var probe=Group("Workshop reflection capture",stage,V(0,2.2f,0)).gameObject.AddComponent<ReflectionProbe>();probe.mode=ReflectionProbeMode.Realtime;probe.refreshMode=ReflectionProbeRefreshMode.OnAwake;probe.timeSlicingMode=ReflectionProbeTimeSlicingMode.AllFacesAtOnce;probe.resolution=256;probe.size=V(42,23,35);probe.center=V(0,2,0);probe.boxProjection=true;probe.cullingMask=1<<28;probe.intensity=.75f;probe.backgroundColor=C("D5CDC0");probe.clearFlags=ReflectionProbeClearFlags.SolidColor;probe.nearClipPlane=.2f;probe.farClipPlane=70;}
 static void AddBallast(Transform parent){var rng=new System.Random(73);var mats=new[]{Mat("Warm granite",C("8D877A"),0,.15f),Mat("Pale granite",C("A6A092"),0,.13f),Mat("Dark granite",C("625F56"),0,.18f)};float t=(1+Mathf.Sqrt(5))/2;var ico=new[]{V(-1,t,0),V(1,t,0),V(-1,-t,0),V(1,-t,0),V(0,-1,t),V(0,1,t),V(0,-1,-t),V(0,1,-t),V(t,0,-1),V(t,0,1),V(-t,0,-1),V(-t,0,1)};int[] faces={0,11,5,0,5,1,0,1,7,0,7,10,0,10,11,1,5,9,5,11,4,11,10,2,10,7,6,7,1,8,3,9,4,3,4,2,3,2,6,3,6,8,3,8,9,4,9,5,2,4,11,6,2,10,8,6,7,9,8,1};for(int material=0;material<3;material++){var vs=new List<Vector3>();var indices=new List<int>();for(int n=0;n<1600;n++){float x=(float)rng.NextDouble()*19.8f-9.9f,z=(float)rng.NextDouble()*2.63f-1.315f,r=.023f+(float)rng.NextDouble()*.036f;Vector3 at=V(x,-.27f,z),scale=V(r*1.2f,r*.6f,r);var rot=Quaternion.Euler((float)rng.NextDouble()*360,(float)rng.NextDouble()*360,(float)rng.NextDouble()*360);for(int j=0;j<faces.Length;j++){indices.Add(vs.Count);vs.Add(at+rot*Vector3.Scale(ico[faces[j]].normalized,scale));}}var m=new Mesh{indexFormat=IndexFormat.UInt32};m.SetVertices(vs);m.SetTriangles(indices,0);m.RecalculateNormals();MeshObject("Graded ballast aggregate",parent,SaveMesh(m,"Ballast_"+material),mats[material]);}}
}
